const fs = require('fs');

const data = fs.readFileSync(0, 'utf8').trim().split(/\s+/).map(Number);
let p = 0;
const N = data[p++];
const M = data[p++];

const G = Array.from({ length: N }, () => Array(M));
for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    G[i][j] = data[p++];
  }
}

let costA = 0;
let costB = 0;

for (let i = 0; i < N; i++) {
  for (let j = 0; j < M; j++) {
    const parity = (i + j) & 1;
    const gParity = G[i][j] & 1;

    if (gParity !== parity) costA++;
    if (gParity !== (1 - parity)) costB++;
  }
}

const useA = costA <= costB;
const minCost = useA ? costA : costB;

const out = [String(minCost)];

for (let i = 0; i < N; i++) {
  const row = [];
  for (let j = 0; j < M; j++) {
    const required = useA ? ((i + j) & 1) : (1 - ((i + j) & 1));
    let v = G[i][j];
    if ((v & 1) !== required) v++;
    row.push(v);
  }
  out.push(row.join(' '));
}

console.log(out.join('\n'));
